// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint96 fundTarget, uint96 fundCaller, address target, address caller) public {
        vm.assume(target != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != target);

        uint256 tAmt = uint256(bound(fundTarget, 0, type(uint128).max));
        uint256 cAmt = uint256(bound(fundCaller, 0, type(uint128).max));

        vm.deal(target, tAmt);
        vm.deal(caller, cAmt);

        if (tAmt > 0) {
            vm.prank(target);
            c.addToBalance{value: tAmt}();
        }

        if (cAmt > 0) {
            vm.prank(caller);
            c.addToBalance{value: cAmt}();
        }

        vm.prank(caller);
        uint256 reported = c.getBalance(target);

        vm.prank(target);
        uint256 actual = c.getBalance(target);

        assertTrue(reported == actual);
    }
}
